select ri.id, ri.room_number, ri.rent, ri.apartment_id, ri.is_release, ai.id apar_id, ai.name, ai.introduction, ai.district_id, ai.district_name, ai.city_id, ai.city_name, ai.province_id, ai.province_name, ai.address_detail, ai.latitude, ai.longitude, ai.phone, ai.is_release apar_is_release, la.lease_end_date, la.room_id is not null isCheckIn from room_info ri left join apartment_info ai on ri.apartment_id=ai.id and ai.is_deleted=0 left join (select room_id, max(lease_end_date) lease_end_date from lease_agreement where is_deleted=0 and status in (2,5) group by room_id) la on la.room_id=ri.id
ri.is_deleted=0
and ai.province_id=#{queryVo.provinceId}
and ai.city_id=#{queryVo.cityId}
and ai.district_id=#{queryVo.districtId}
and ai.id=#{queryVo.apartmentId}
